// ═══ mapMulti: filter + transform in one step ═══
// For each trade, emit amount ONLY if settled (0 or 1 element):
List<BigDecimal> settledAmounts = trades.stream()
    .<BigDecimal>mapMulti((trade, consumer) -> {
        if (trade.isSettled()) {
            consumer.accept(trade.getAmount());  // push 1 element
        }
        // not settled → push nothing (0 elements)
    })
    .toList();

// ═══ Equivalent flatMap (creates Stream per element — overhead!) ═══
List<BigDecimal> flatMapVersion = trades.stream()
    .flatMap(t -> t.isSettled() ? Stream.of(t.getAmount()) : Stream.empty())
    .toList();
// Each trade creates a Stream.of or Stream.empty — mapMulti avoids this!

// ═══ mapMulti: one-to-many expansion ═══
List<String> expanded = List.of("RELIANCE:BUY:SELL", "TCS:BUY").stream()
    .<String>mapMulti((line, consumer) -> {
        String[] parts = line.split(":");
        String symbol = parts[0];
        for (int i = 1; i < parts.length; i++) {
            consumer.accept(symbol + "-" + parts[i]);  // push multiple
        }
    })
    .toList();
// ["RELIANCE-BUY", "RELIANCE-SELL", "TCS-BUY"]

// ═══ mapMultiToInt: primitive version ═══
int totalQty = trades.stream()
    .mapMultiToInt((trade, consumer) -> {
        if (trade.isSettled()) consumer.accept(trade.getQuantity());
    })
    .sum();
