@Test void mapMultiFilterAndTransform() {
    record Trade(String id, boolean settled, int amount) {}
    List<Integer> amounts = List.of(new Trade("T1", true, 100), new Trade("T2", false, 200),
        new Trade("T3", true, 300)).stream()
        .<Integer>mapMulti((t, c) -> { if (t.settled()) c.accept(t.amount()); })
        .toList();
    assertThat(amounts).containsExactly(100, 300);  // T2 excluded (not settled)
}

@Test void mapMultiOneToMany() {
    List<String> result = List.of(2, 3).stream()
        .<String>mapMulti((n, c) -> { for (int i = 0; i < n; i++) c.accept(""); })
        .toList();
    assertThat(result).containsExactly("", "", "", "", "");  // 2+3
}
