package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

class MapMultiTest {

    record Trade(String id, int legs) {}

    @Test
    void mapMultiEmitsZeroOrMore() {
        var trades = List.of(new Trade("T1", 1), new Trade("T2", 3));

        List<String> expanded = trades.stream()
            .<String>mapMulti((t, downstream) -> {
                for (int i = 1; i <= t.legs(); i++) downstream.accept(t.id() + "-L" + i);
            })
            .toList();

        assertThat(expanded).containsExactly("T1-L1", "T2-L1", "T2-L2", "T2-L3");
    }
}
